  material_ammolite_description:
    "\u090F\u0915 \u0935\u093F\u0932\u0941\u092A\u094D\u0924 \u0905\u092E\u094B\u0928\u093E\u0907\u091F \u0915\u093E \u0907\u0930\u093F\u0921\u0947\u0938\u0947\u0902\u091F \u0915\u0935\u091A, \u0905\u0932\u092C\u0930\u094D\u091F\u093E \u0915\u0940 \u0938\u0947\u0902\u091F \u092E\u0947\u0930\u0940 \u0928\u0926\u0940 \u0915\u0940 \u090F\u0915 \u0938\u0902\u0915\u0940\u0930\u094D\u0923 \u092A\u091F\u094D\u091F\u0940 \u092E\u0947\u0902 \u092A\u093E\u092F\u093E \u091C\u093E\u0924\u093E \u0939\u0948\u0964 \u0930\u0924\u094D\u0928-\u0917\u0941\u0923\u0935\u0924\u094D\u0924\u093E \u0938\u093E\u092E\u0917\u094D\u0930\u0940 \u0915\u0941\u091B \u0926\u0936\u0915\u094B\u0902 \u092E\u0947\u0902 \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B \u0938\u0915\u0924\u0940 \u0939\u0948\u0964",

