  "material_amber-inclusion_tagline":
    "\u090F\u0915 \u092A\u0942\u0930\u093E \u091C\u0940\u0935, 4 \u0915\u0930\u094B\u0921\u093C \u0938\u093E\u0932\u094B\u0902 \u0938\u0947 \u0935\u0943\u0915\u094D\u0937-\u0930\u0947\u091C\u093F\u0928 \u092E\u0947\u0902 \u091C\u092E\u093E",
  "material_amber-inclusion_description":
    "\u0939\u091C\u093C\u093E\u0930 \u0905\u0902\u092C\u0930 \u091F\u0941\u0915\u0921\u093C\u094B\u0902 \u092E\u0947\u0902 \u090F\u0915 \u092E\u0947\u0902 \u0915\u0940\u091F \u0939\u094B\u0924\u093E \u0939\u0948\u0964 \u0915\u0947\u0935\u0932 10% \u0907\u0924\u0928\u0947 \u0905\u091A\u094D\u091B\u0947 \u0938\u0902\u0930\u0915\u094D\u0937\u093F\u0924 \u0939\u0948\u0902 \u0915\u093F \u092A\u0939\u091A\u093E\u0928\u0947 \u091C\u093E \u0938\u0915\u0947\u0902\u0964 \u0939\u0930 \u090F\u0915 \u092A\u0947\u0921\u093C \u0915\u0947 \u0918\u093E\u0935 \u092A\u0930 \u0917\u093F\u0930\u093E \u0914\u0930 \u0915\u092D\u0940 \u0935\u093E\u092A\u0938 \u0928\u0939\u0940\u0902 \u0906\u092F\u093E\u0964",

