  material_moldavite_tagline:
    "\u092A\u0943\u0925\u094D\u0935\u0940 \u0915\u0940 \u092D\u0942\u092A\u0930\u094D\u092A\u091F\u0940, \u090F\u0915 \u092C\u094D\u0930\u0939\u094D\u092E\u093E\u0923\u094D\u0921\u0940\u092F \u091F\u0915\u094D\u0915\u0930 \u0938\u0947 \u0915\u093E\u0901\u091A \u092E\u0947\u0902 \u092C\u0926\u0932\u0940",
  material_moldavite_description:
    "1.48 \u0915\u0930\u094B\u0921\u093C \u0938\u093E\u0932 \u092A\u0939\u0932\u0947 \u090F\u0915 \u0915\u094D\u0937\u0941\u0926\u094D\u0930\u0917\u094D\u0930\u0939 \u0928\u0947 \u092C\u0935\u0947\u0930\u093F\u092F\u093E \u0915\u093E \u090F\u0915 \u0939\u093F\u0938\u094D\u0938\u093E \u092D\u093E\u092A \u0926\u093F\u092F\u093E\u0964 \u092A\u093F\u0918\u0932\u093E \u0915\u093E\u0901\u091A \u0909\u0921\u093C\u093E\u0928 \u0915\u0947 \u0926\u094C\u0930\u093E\u0928 \u091C\u092E \u0917\u092F\u093E\u0964 275 \u091F\u0928 \u092C\u091A\u093E \u0939\u0948\u0964 \u0914\u0930 \u0915\u092D\u0940 \u0928\u0939\u0940\u0902 \u092C\u0928\u0947\u0917\u093E\u0964",

