  material_pearl_tagline:
    "\u0905\u092C \u0924\u0915 \u092C\u0928\u0940 \u0938\u092D\u0940 \u092A\u094D\u0930\u093E\u0915\u0943\u0924\u093F\u0915 \u092E\u094B\u0924\u093F\u092F\u093E\u0901 \u090F\u0915 \u0915\u092E\u0930\u0947 \u092E\u0947\u0902 \u0938\u092E\u093E \u091C\u093E\u090F\u0901\u0917\u0940\u0964",
  material_pearl_description:
    "\u0926\u0938 \u0939\u091C\u093C\u093E\u0930 \u091C\u0902\u0917\u0932\u0940 \u0938\u0940\u092A\u094B\u0902 \u092E\u0947\u0902 \u0938\u0947 \u090F\u0915 \u092E\u0947\u0902 \u0930\u0924\u094D\u0928-\u0917\u0941\u0923\u0935\u0924\u094D\u0924\u093E \u092E\u094B\u0924\u0940 \u092C\u0928\u0924\u0940 \u0939\u0948\u0964 \u092A\u0930\u0924 \u0926\u0930 \u092A\u0930\u0924, \u090F\u0915 \u0938\u0941\u0930\u0915\u094D\u0937\u093E\u0924\u094D\u092E\u0915 \u092A\u0930\u0924 \u0915\u093F\u0938\u0940 \u092C\u093E\u0939\u0930\u0940 \u0915\u0923 \u0915\u0947 \u090A\u092A\u0930 \u092C\u0928\u0924\u0940 \u0939\u0948 \u091C\u093F\u0938\u0947 \u091C\u0940\u0935 \u0928\u093F\u0915\u093E\u0932 \u0928\u0939\u0940\u0902 \u092A\u093E\u0924\u093E\u0964 \u092A\u0939\u0928\u0928\u0947 \u092F\u094B\u0917\u094D\u092F \u0939\u0930 \u0930\u0924\u094D\u0928 \u092E\u0947\u0902, \u092F\u0939 \u0938\u092C\u0938\u0947 \u0926\u0941\u0930\u094D\u0932\u092D \u0939\u0948\u0964",
  material_pearl_scaleComparison:
    "\u0905\u092C \u0924\u0915 \u092C\u0928\u0940 \u0938\u092D\u0940 \u092A\u094D\u0930\u093E\u0915\u0943\u0924\u093F\u0915 \u092E\u094B\u0924\u093F\u092F\u093E\u0901 \u090F\u0915 \u0915\u092E\u0930\u0947 \u092E\u0947\u0902 \u0938\u092E\u093E \u091C\u093E\u090F\u0901\u0917\u0940\u0964",
